import React, { useEffect, useState } from 'react';
import { SafeAreaView, Text, StyleSheet, Button, View } from 'react-native';
import ProductList from '../components/ProductList';
import BrandLogo from '../components/BrandLogo';

export default function HomeScreen({ navigation }) {
  const [products, setProducts] = useState([]);

  useEffect(() => {
    fetch('http://localhost:3000/api/products')
      .then(res => res.json())
      .then(data => setProducts(data))
      .catch(() => setProducts([]));
  }, []);

  return (
    <SafeAreaView style={styles.container}>
      <View style={styles.brandRow}>
        <BrandLogo />
      </View>
      <View style={styles.buttonsRow}>
        <Button title="Etsi paikan mukaan" onPress={() => navigation.navigate('MapSearch')} />
        <Button title="Profiili" onPress={() => navigation.navigate('Profile')} />
      </View>
      <Text style={styles.title}>Vuokrattavat tuotteet</Text>
      <ProductList products={products} navigation={navigation} />
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: 16 },
  brandRow: { flexDirection: 'row', alignItems: 'center', marginBottom: 16 },
  buttonsRow: { flexDirection: 'row', justifyContent: 'space-between', marginBottom: 16 },
  logo: { width: 56, height: 56, marginRight: 12 },
  brandText: { flex: 1 },
  brand: { fontSize: 26, fontWeight: '800' },
  subtitle: { color: '#555' },
  title: { fontSize: 20, fontWeight: '600', marginVertical: 16 }
});
